import { NextResponse } from 'next/server';
import Stripe from 'stripe';

// Initialize Stripe with the secret key from environment variables
const stripe = new Stripe(process.env.STRIPE_SECRET_KEY || 'sk_test_mock', {
  apiVersion: '2026-07-29.dahlia',
});

export async function POST(req: Request) {
  try {
    // In a real app, you would get the user ID from the session and pass it as client_reference_id
    // to map the payment back to the user in the webhook.
    
    // Create Checkout Sessions from body params.
    const session = await stripe.checkout.sessions.create({
      payment_method_types: ['card'],
      line_items: [
        {
          price_data: {
            currency: 'usd',
            product_data: {
              name: 'Synqra Plus Subscription',
              description: 'Unlimited sparks, see who liked you, and aura boosts.',
            },
            unit_amount: 1499, // $14.99
            recurring: {
              interval: 'month',
            }
          },
          quantity: 1,
        },
      ],
      mode: 'subscription',
      success_url: `${req.headers.get('origin')}/discover?success=true`,
      cancel_url: `${req.headers.get('origin')}/premium?canceled=true`,
    });

    return NextResponse.json({ url: session.url });
  } catch (err: any) {
    console.error('Stripe error:', err);
    return NextResponse.json({ error: err.message }, { status: 500 });
  }
}
